<script setup>import {ref,onMounted,onUnmounted} from 'vue';import {watchStorage,uploadSmall} from '../services/data';import {httpsCallable} from 'firebase/functions';import {functions} from '../firebase';const props=defineProps(['user']);const emit=defineEmits(['toast']);const links=ref([]),form=ref({name:'',description:'',category:'Oyun',downloadUrl:'',storageId:'',banner:null,screens:[]}),status=ref(''),busy=ref(false);let stop;onMounted(()=>stop=watchStorage(props.user.uid,v=>links.value=v));onUnmounted(()=>stop?.());function screens(e){form.value.screens=[...e.target.files].slice(0,5)}async function submit(){busy.value=true;status.value='';try{if(!form.value.name||!form.value.description||!form.value.downloadUrl||!form.value.storageId||!form.value.banner)throw Error('Ad, açıklama, kategori, depolama, indirme linki ve banner zorunlu.');if(form.value.banner.size>5*1024*1024)throw Error('Banner 5 MB sınırını aşamaz.');status.value='Görseller yükleniyor...';const banner=await uploadSmall(props.user.uid,form.value.banner,'banners');const screenshots=[];for(const f of form.value.screens)screenshots.push(await uploadSmall(props.user.uid,f,'screens'));status.value='VirusTotal taraması yapılıyor...';const publish=httpsCallable(functions,'scanAndPublish');const result=await publish({name:form.value.name.trim(),description:form.value.description.trim(),category:form.value.category,downloadUrl:form.value.downloadUrl.trim(),storageId:form.value.storageId,banner,screenshots});if(!result.data?.safe)throw Error('Güvenlik taraması temiz çıkmadı. Yayın reddedildi.');status.value='🛡 Safe — uygulaman yayınlandı.';emit('toast','Uygulama güvenlik kontrolünden geçti.')}catch(e){status.value='❌ '+(e.message||'Yayın başarısız.')}finally{busy.value=false}}</script><template><h1>Uygulama Yayınla</h1><div class="card"><p class="muted">Dosyanı yüklemiyoruz. Yalnızca kendi depolama servisindeki indirme bağlantısını kaydediyoruz.</p><div class="grid"><input class="field" v-model="form.name" maxlength="80" placeholder="Uygulama adı *"><select class="field" v-model="form.category"><option>Oyun</option><option>Üretkenlik</option><option>Eğitim</option><option>Araçlar</option><option>Diğer</option></select></div><textarea class="field" rows="5" v-model="form.description" maxlength="3000" placeholder="Açıklama *"></textarea><select class="field" v-model="form.storageId"><option value="">Bağlı depolama seç *</option><option v-for="x in links" :value="x.id">{{x.name}}</option></select><input class="field" v-model="form.downloadUrl" type="url" placeholder="İndirme linki *"><label>Banner — maksimum 5 MB *</label><input class="field" type="file" accept="image/*" @change="form.banner=$event.target.files[0]||null"><label>Ekran görüntüleri — maksimum 5 adet, her biri 5 MB</label><input class="field" type="file" accept="image/*" multiple @change="screens"><button class="btn" :disabled="busy" @click="submit">{{busy?'Kontrol ediliyor...':'🛡 Tara ve yayınla'}}</button><p v-if="status">{{status}}</p></div></template>